import Header from '../components/Header';
import Hero from '../components/Hero';
import TopAstrologers from '../components/TopAstrologers';
import HowItWorks from '../components/HowItWorks';
import WhyChoose from '../components/WhyChoose';
import Testimonials from '../components/Testimonials';
import FAQs from '../components/FAQs';
import Footer from '../components/Footer';
import { fetchPublicAstrologers } from '@/lib/publicApi';

export default async function Home() {
  const topAstrologers = await fetchPublicAstrologers({ limit: 12, revalidate: 60 });

  return (
    <div className="min-h-screen bg-background">
      <Header />
      <Hero />
      <TopAstrologers astrologers={topAstrologers} />
      <HowItWorks />
      <WhyChoose />
      <Testimonials />
      <FAQs />
      <Footer />
    </div>
  );
}